    List<List<JSONObject>> groupCache;Map<String,List<JSONObject>> groupIndex=new HashMap<>();long groupVersion=-1;
    List<List<JSONObject>> groups(){long version=data.version;if(groupCache==null||groupVersion!=version){Map<String,List<JSONObject>> m=new LinkedHashMap<>();for(JSONObject i:DataStore.objects(data.itemsShared()))m.computeIfAbsent(i.optString("group"),k->new ArrayList<>()).add(i);List<List<JSONObject>> groups=new ArrayList<>(m.values());groups.sort(Comparator.comparing(g->g.get(0).optString("title")));for(List<JSONObject> g:groups)g.sort(Comparator.comparingInt((JSONObject i)->i.optInt("season")==0?999:i.optInt("season")).thenComparingInt(i->i.optInt("episode")));groupCache=groups;groupIndex=m;groupVersion=version;}return new ArrayList<>(groupCache);}
