    static double position(JSONObject i){JSONObject p=i.optJSONObject("progress");return p==null?0:p.optDouble("position",0);}
    static boolean completed(JSONObject i){JSONObject p=i.optJSONObject("progress");return p!=null&&p.optBoolean("completed");}
    boolean playable(JSONObject i){return !data.localFile(i.optString("id")).isEmpty()||data.paired()&&data.online&&i.optBoolean("available");}
    static long recent(List<JSONObject> g){return g.stream().mapToLong(DataStore::recent).max().orElse(0);}
