    // Home: a cinematic hero for the most relevant title, one Continue Watching row (resume, next,
    // get-it-on-PC and waiting shows), then rows to browse.
    void home(){List<List<JSONObject>> groups=groups();if(groups.isEmpty()){heading("Continue Watching");homeLayout.render(groups);return;}List<NoirUi.Next> continuing=ui.continuing();
        NoirUi.Next top=continuing.stream().filter(n->!n.kind.equals(NoirUi.UPCOMING)).findFirst().orElse(null);
        if(top!=null){List<JSONObject> g=group(top.item.optString("group"));JSONObject show=top.item.optBoolean("placeholder")||g==null?(g==null?top.item:g.get(0)):top.item;
            String eyebrow=top.kind.equals(NoirUi.RESUME)?"RIGHT WHERE YOU LEFT OFF":top.kind.equals(NoirUi.MISSING)?"UP NEXT · NOT ON YOUR PC YET":"UP NEXT · "+episode(top.item);
            ui.hero(body,show,g==null?List.of(show):g,eyebrow,(top.kind.equals(NoirUi.MISSING)?"↓ ":"▶ ")+ui.action(top),()->ui.act(top),false);}
        else{JSONObject pick=groups.stream().filter(g->g.stream().anyMatch(this::playable)).map(g->g.get(0)).findFirst().orElse(groups.get(0).get(0));List<JSONObject> g=group(pick.optString("group"));ui.hero(body,pick,g,"TONIGHT'S PICK","▶ Play",()->open(pick),false);}
        List<View> cards=new ArrayList<>();for(NoirUi.Next n:continuing)cards.add(ui.continueCard(n));
        if(cards.isEmpty())heading("Continue Watching");ui.rail(body,"Continue Watching",continuing.stream().anyMatch(n->n.kind.equals(NoirUi.MISSING))?"Resume, play next, or send the next episode to your PC.":"Resume or play the next episode.",cards,null);
        homeLayout.render(groups);}
