    ImageView poster(JSONObject i,boolean portrait){long revision=renderRevision;ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setContentDescription(i.optString("title")+" "+Loc.t("artwork"));String name=i.optString(portrait?"poster":!i.optString("episodeImage").isEmpty()&&(!browsingSettings().optBoolean("hideSpoilers",true)||DataStore.watched(i))?"episodeImage":"backdrop");if(name.isEmpty())name=i.optString("poster");File file=data.art(name);for(String fallback:new String[]{i.optString("backdrop"),i.optString("poster")})if(!file.exists()&&!fallback.isEmpty())file=data.art(fallback);final File source=file;String url=i.optString(portrait?"posterUrl":"backdropUrl",i.optString("posterUrl"));if(url.isEmpty())url=i.optString("posterUrl");if(url.isEmpty()&&!source.exists())url=data.phoneArt(i.optString("imdb"),portrait?"posterUrl":"backdropUrl");if(url.isEmpty()&&!source.exists())url=data.phoneArt(i.optString("imdb"),"posterUrl");final String remote=url,key=url.isEmpty()?source.getPath():url;image.setBackground(bg(Motion.placeholder(key),dp(12)));if(!source.exists()&&!remote.startsWith("https://"))return image;data.images.execute(()->{try{Bitmap bitmap;if(source.exists()){BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(source.getPath(),o);o.inSampleSize=Math.max(1,o.outWidth/700);o.inJustDecodeBounds=false;bitmap=BitmapFactory.decodeFile(source.getPath(),o);}else{if(discovery==null)discovery=new DiscoveryClient(this);bitmap=discovery.art(remote);}if(bitmap!=null){Motion.remember(key,bitmap);runOnUiThread(()->{if(!isDestroyed()&&revision==renderRevision){Motion.loaded(image,bitmap,key);HomeLayout.tint(image,key);}});}}catch(Exception ignored){}});return image;}
    String count(List<JSONObject> g){JSONObject i=g.get(0);if(i.optBoolean("movie"))return i.optInt("year")>0?""+i.optInt("year"):"Movie";long regular=g.stream().filter(x->x.optInt("season")>0).count(),special=g.size()-regular,watched=g.stream().filter(DataStore::watched).count();return regular+" episodes"+(special>0?" + "+special+" specials":"")+" · "+watched+" watched";}
