    // Title page: hero artwork with the main action, a row of action chips, then compact episode rows.
    void details(){List<JSONObject> group=null;for(List<JSONObject> g:groups())if(g.get(0).optString("group").equals(detail))group=g;if(group==null){detail="";render();return;}JSONObject first=group.get(0);if(PhoneExperience.trackerOnly(data)){tracker.details(group);return;}
        TextView back=ui.small("‹ Back",()->{detail="";render();},false);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.setMargins(0,dp(4),0,dp(8));back.setLayoutParams(bp);body.addView(back);
        NoirUi.Next next=ui.next(group);JSONObject current=continuation(group);if(current==null)current=group.stream().filter(i->playable(i)&&!completed(i)).findFirst().orElse(first);JSONObject target=current;
        String primary=position(target)>=1&&!completed(target)?"▶ Resume "+episode(target)+" · "+DataStore.time(position(target)):playable(target)?"▶ Play "+(first.optBoolean("movie")?"":episode(target)):next!=null&&next.kind.equals(NoirUi.MISSING)?"↓ Get "+NoirUi.compact(next.item)+" on PC":"Download to PC";
        Runnable primaryAction=playable(target)?()->play(target,false):next!=null&&next.kind.equals(NoirUi.MISSING)?()->pcDownload(next.item,false):()->pcDownload(target,false);
        // Nothing to play here or on the PC: stream it through the phone's AIOStreams link.
        if(!playable(target)){JSONObject streamTarget=next!=null&&next.kind.equals(NoirUi.MISSING)?next.item:target;primary=PhoneStream.available(this)?"▶ Stream "+(first.optBoolean("movie")?"":episode(streamTarget)):"Set up streaming";primaryAction=()->PhoneStream.start(this,streamTarget,false);}
        ui.hero(body,first,group,next!=null&&next.kind.equals(NoirUi.UPCOMING)?"NEXT EPISODE · "+NoirUi.date(next.airsAt).toUpperCase(Locale.ROOT):premium.label(group).toUpperCase(Locale.ROOT),primary,primaryAction,true);
        TextView synopsis=text(first.optString("showSummary"),14,MUTED);synopsis.setMaxLines(3);synopsis.setEllipsize(android.text.TextUtils.TruncateAt.END);synopsis.setPadding(0,dp(10),0,dp(8));synopsis.setOnClickListener(v->synopsis.setMaxLines(Integer.MAX_VALUE));synopsis.setTooltipText("Tap to read the full description");body.addView(synopsis);body.addView(PhoneCredits.castStrip(this,first));if(!first.optBoolean("movie"))body.addView(PhoneTracker.seasonStrip(this,group));
        LinearLayout actions=new LinearLayout(this);actions.addView(ui.chip("💬 Reviews",()->reviews(first),false));actions.addView(ui.chip("◐ "+premium.label(group),()->premium.status(first),false));actions.addView(ui.chip("＋ Collection",()->premium.collections(first),false));
        final List<JSONObject> libraryGroup=group;if(inLibrary(group))actions.addView(ui.chip("✕ Remove",()->removeFromLibrary(first,libraryGroup),false));else actions.addView(ui.chip("＋ Library",()->{data.library(first.optString("id"),true);render();toast("Added to your library");},false));
        if(first.optBoolean("movie")){actions.addView(ui.chip("↓ Download to phone",()->PhoneDownloadsActivity.open(this,first,false),false));if(data.paired())actions.addView(ui.chip("↓ Download to PC",()->pcDownload(first,false),false));actions.addView(ui.chip("⋯ More",()->options(first),false));body.addView(ui.row(actions));return;}
        final List<JSONObject> allEpisodes=group;TreeSet<Integer> seasons=new TreeSet<>();for(JSONObject i:group)seasons.add(i.optInt("season"));if(detailSeason<0||!seasons.contains(detailSeason))detailSeason=target.optInt("season");
        JSONObject downloadTarget=group.stream().filter(i->i.optInt("season")==detailSeason).findFirst().orElse(first);actions.addView(ui.chip("↓ Season "+detailSeason+" to phone",()->PhoneDownloadsActivity.open(this,downloadTarget,true),false));if(data.paired())actions.addView(ui.chip("↓ Season "+detailSeason+" to PC",()->pcDownload(downloadTarget,true),false));
        boolean allSeen=smart.released(first).stream().allMatch(DataStore::watched);if(!allSeen)actions.addView(ui.chip("✓ Whole show",()->smart.wholeShow(first),false));
        final int ratedSeason=detailSeason;List<JSONObject> seasonOut=new ArrayList<>();for(JSONObject x:smart.released(first))if(x.optInt("season")==ratedSeason&&!DataStore.watched(x))seasonOut.add(x);if(!seasonOut.isEmpty())actions.addView(ui.chip("✓ Season "+ratedSeason,()->smart.bulk(seasonOut,first.optString("title")+" season "+ratedSeason+" marked watched"),false));body.addView(ui.row(actions));
        String[] seasonLabels=seasons.stream().map(n->n==0?"Specials":"Season "+n).toArray(String[]::new);LinearLayout seasonRow=new LinearLayout(this);for(String label:seasonLabels)seasonRow.addView(ui.chip(label,()->{detailSeason=label.equals("Specials")?0:Integer.parseInt(label.substring(7));render();},label.equals(detailSeason==0?"Specials":"Season "+detailSeason)));TextView spacer=new TextView(this);spacer.setPadding(0,dp(14),0,0);body.addView(spacer);body.addView(ui.row(seasonRow));
        final int selectedSeason=detailSeason;long total=group.stream().filter(x->x.optInt("season")==selectedSeason).count(),seen=group.stream().filter(x->x.optInt("season")==selectedSeason&&DataStore.watched(x)).count();
        TextView progressLabel=text(seen+" of "+total+" watched",12,MUTED);progressLabel.setPadding(0,dp(4),0,dp(6));body.addView(progressLabel);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax((int)Math.max(1,total));progress.setProgress((int)seen);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(GOLD));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(6));pp.setMargins(0,0,0,dp(14));body.addView(progress,pp);
        for(JSONObject i:group){if(i.optInt("season")!=detailSeason)continue;body.addView(episodeRow(i));}}
    // A compact episode row: thumbnail with progress, title and status; tap to play, ⋯ for options.
    View episodeRow(JSONObject i){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),dp(10),dp(6),dp(10));row.setBackground(bg(PANEL,dp(14)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));row.setLayoutParams(lp);
        FrameLayout thumb=ui.art(i,false,dp(124),dp(70));JSONObject p=i.optJSONObject("progress");double d=p==null?i.optDouble("duration",0):p.optDouble("duration",i.optDouble("duration",0));
        if(position(i)>0&&!completed(i)&&d>0){ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)(1000*position(i)/d));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(GOLD));thumb.addView(bar,new FrameLayout.LayoutParams(-1,dp(5),Gravity.BOTTOM));}
        if(DataStore.watched(i)){TextView check=ui.pill("✓",BLACK,GOLD);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.END);cp.setMargins(0,dp(6),dp(6),0);thumb.addView(check,cp);}
        if(playable(i)){TextView glyph=text("▶",16,WHITE);glyph.setGravity(Gravity.CENTER);glyph.setBackground(bg(Color.argb(170,12,12,14),dp(16)));thumb.addView(glyph,new FrameLayout.LayoutParams(dp(32),dp(32),Gravity.CENTER));}
        row.addView(thumb);LinearLayout info=column();LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-2,1);ip.setMargins(dp(12),0,dp(4),0);row.addView(info,ip);
        boolean spoilerFree=!browsingSettings().optBoolean("hideSpoilers",true)||DataStore.watched(i);
        TextView title=text("E"+i.optInt("episode")+"  "+(spoilerFree||i.optString("episodeTitle").isEmpty()?i.optString("episodeTitle"):"Episode "+i.optInt("episode")),14,WHITE);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(title);
        String status=completed(i)?"✓ Watched":position(i)>0?"Resume "+DataStore.time(position(i)):!data.localFile(i.optString("id")).isEmpty()?"On this phone":i.optBoolean("available")?"Stream from PC":"Not on your PC";
        if(d>60)status+=" · "+(int)(d/60)+" min";if(ui.isNew(i))status="NEW · "+status;info.addView(text(status,12,completed(i)||ui.isNew(i)?GOLD:MUTED));
        TextView more=text("⋯",20,MUTED);more.setPadding(dp(10),dp(4),dp(8),dp(4));more.setContentDescription("Options for "+episode(i));more.setOnClickListener(v->options(i));row.addView(more);
        row.setOnClickListener(v->{if(playable(i))play(i,false);else options(i);});row.setOnLongClickListener(v->{options(i);return true;});return row;}
    void options(JSONObject i){titleActions.show(i);}
    // Opens the exact movie or episode in the Stremio app, or Stremio Web when the app isn't installed.
    void stremio(JSONObject i){
        String imdb=i.optString("imdb");if(!imdb.matches("tt\\d+")){toast("This title needs a verified match before it can open in Stremio.");return;}boolean movie=i.optBoolean("movie");String video=movie?imdb:imdb+":"+i.optInt("season")+":"+i.optInt("episode");
        String path="/detail/"+(movie?"movie":"series")+"/"+imdb+"/"+Uri.encode(video);
        try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("stremio://"+path)));}
        catch(android.content.ActivityNotFoundException e){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://web.stremio.com/#"+path)));}catch(android.content.ActivityNotFoundException none){toast("Install Stremio to stream this title.");}}
    }
    // Nuvio's own deep link (AppUrlBridge.buildMetaDeepLinkUrl) opens the title page; it has no episode form.
    void nuvio(JSONObject i){
        String imdb=i.optString("imdb");if(!imdb.matches("tt\\d+")){toast("This title needs a verified match before it can open in Nuvio.");return;}
        try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("nuvio://meta?type="+(i.optBoolean("movie")?"movie":"series")+"&id="+imdb)));}
        catch(android.content.ActivityNotFoundException e){toast("Install Nuvio to stream this title.");try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://nuvio.tv")));}catch(android.content.ActivityNotFoundException none){}}
    }
    void option(JSONObject i,int n){switch(n){case 0:if(playable(i))play(i,false);break;case 1:if(playable(i))play(i,true);break;case 2:if(DataStore.watched(i))smart.watchedClick(i);else smart.checkOff(i,i.optString("title")+" "+episode(i)+" watched");break;case 3:attachId=i.optString("id");Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","application/octet-stream"}).addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(pick,9);break;case 4:reviews(i);break;case 5:rating(i);break;case 6:StringBuilder dates=new StringBuilder();for(JSONObject v:DataStore.objects(i.optJSONArray("viewings")))dates.append(java.time.Instant.ofEpochMilli(DataStore.date(v.optString("watchedAt"))).atZone(java.time.ZoneId.systemDefault()).toLocalDate()).append(" · ").append(v.optString("source")).append('\n');new AlertDialog.Builder(this).setTitle("Viewing history").setMessage(dates.length()>0?dates.toString():"No completed viewing recorded yet.").setPositiveButton("OK",null).show();break;case 7:data.queueVideo(i.optString("id"));toast("Added to your phone play queue");break;case 8:premium.status(i);break;case 9:premium.collections(i);break;case 10:download(i,true);break;case 11:premium.match(i);break;case 12:download(i,false);break;case 13:new AlertDialog.Builder(this).setTitle(i.optString("episodeTitle")).setMessage(i.optString("summary")).setPositiveButton("Close",null).show();break;case 14:pcDownload(i,false);break;case 15:pcDownload(i,true);break;}}
    void rating(JSONObject i){LinearLayout panel=column();panel.setPadding(dp(20),dp(10),dp(20),0);RatingBar stars=new RatingBar(this,null,android.R.attr.ratingBarStyleSmall);stars.setIsIndicator(false);stars.setNumStars(5);stars.setStepSize(1);JSONObject r=i.optJSONObject("review");stars.setRating(r==null?0:r.optInt("rating"));panel.addView(stars);EditText note=new EditText(this);note.setHint("Your private note");note.setText(r==null?"":r.optString("note"));note.setMinLines(3);panel.addView(note);new AlertDialog.Builder(this).setTitle("My rating & note").setView(panel).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{JSONObject op=data.operation(i.optString("id"),"review");DataStore.put(op,"rating",(int)stars.getRating());DataStore.put(op,"note",note.getText().toString());data.queue(op);data.syncSoon();toast("Saved. Syncs when your PC is available.");}).show();}
    boolean launching=false;void play(JSONObject i,boolean restart){if(!playable(i)||launching)return;launching=true;String id=i.optString("id");if(!data.localFile(id).isEmpty()){launching=false;startActivity(new Intent(this,PlayerActivity.class).putExtra("id",id).putExtra("restart",restart));data.syncSoon();return;}toast("Checking latest saved position…");data.network.execute(()->{try{data.sync();}catch(Exception ignored){}JSONObject latest=data.item(id);if(latest!=null)try{data.cacheSubtitles(latest);}catch(Exception ignored){}runOnUiThread(()->{launching=false;if(!active)return;if(data.localFile(id).isEmpty()&&!data.online){toast("PC is offline. Connect to the same Wi-Fi, or link a copy on your phone.");return;}startActivity(new Intent(this,PlayerActivity.class).putExtra("id",id).putExtra("restart",restart));});});}void pcDownload(JSONObject item,boolean season){startActivity(new Intent(this,PcDownloadsActivity.class).putExtra("id",item.optString("id")).putExtra("season",season));}
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==9&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){try{getContentResolver().takePersistableUriPermission(intent.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);data.localFile(attachId,intent.getData().toString());render();toast("Phone copy linked. You can play it offline.");}catch(Exception e){toast("Couldn't retain access to that file. Try another folder provider.");}}}
    void reviews(JSONObject i){startActivity(new Intent(this,ReviewsActivity.class).putExtra("id",i.optString("id")));}
    void pairInput(){EditText input=new EditText(this);input.setHint("noir://pair?…");input.setSingleLine(false);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);new AlertDialog.Builder(this).setTitle("Pair with Noir on your PC").setMessage("Open Noir → Settings → Pair a phone. Paste its pairing link here, or scan its QR code with your camera.").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Connect",(d,w)->pair(input.getText().toString())).show();}
    // Switches the app language; Arabic mirrors every screen, like the PC.
    void setLanguage(String language){data.pref("language",language);Loc.use(data);Loc.apply(this);render();}
    void settings(){PhoneExperience.settings(this);}
    void download(JSONObject i,boolean watch){if(!i.optBoolean("available")||!data.online){toast("Connect to your PC to save this video.");return;}try{NoirApp.downloads.enqueue(i);startForegroundService(new Intent(this,DownloadService.class));if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},12);toast("Queued for offline viewing");if(watch)play(i,false);}catch(Exception e){toast(e.getMessage());}}
    void toast(String s){Toast.makeText(this,Loc.t(s),Toast.LENGTH_LONG).show();}
    void renderKeep(){int y=scroller==null?0:scroller.getScrollY();render();scroller.post(()->scroller.scrollTo(0,y));}
    // Every tracker change can be taken back for a few seconds from a bar above the navigation.
    void undoable(String text,Runnable undo){undoText=text;undoAction=undo;undoUntil=System.currentTimeMillis()+7000;undoBar();handler.postDelayed(()->{if(System.currentTimeMillis()>=undoUntil&&undoView!=null){root.removeView(undoView);undoView=null;undoAction=null;}},7100);}
    void undoBar(){if(undoView!=null&&undoView.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)undoView.getParent()).removeView(undoView);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(18),dp(4),dp(6),dp(4));GradientDrawable b=bg(Color.rgb(28,28,31),dp(22));b.setStroke(dp(1),Color.argb(90,228,192,132));bar.setBackground(b);
        TextView t=text(undoText,13,WHITE);t.setSingleLine();t.setEllipsize(android.text.TextUtils.TruncateAt.END);bar.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView u=text("Undo",14,GOLD);u.setTypeface(null,Typeface.BOLD);u.setPadding(dp(16),dp(10),dp(16),dp(10));u.setOnClickListener(v->{Runnable act=undoAction;undoUntil=0;undoAction=null;if(act!=null)act.run();renderKeep();});bar.addView(u);
        LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(14),dp(4),dp(14),dp(6));root.addView(bar,root.indexOfChild(nav),p);undoView=bar;Motion.riseIn(bar,0);}
    void listBadges(String group,boolean listed){updateListBadge(body,"my-list:"+group,listed);}
    void updateListBadge(View host,String key,boolean listed){if(key.equals(host.getTag())&&host instanceof TextView)((TextView)host).setText(Loc.t(listed?"✓ My List":"+ My List"));if(host instanceof ViewGroup)for(int n=0;n<((ViewGroup)host).getChildCount();n++)updateListBadge(((ViewGroup)host).getChildAt(n),key,listed);}
    String syncStatus(){String value=Loc.t("Saved on phone");if(data.lastSync()>0)value+=" · "+Loc.f("Synced %s",java.time.Instant.ofEpochMilli(data.lastSync()).atZone(java.time.ZoneId.systemDefault()).toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm")));if(syncing)value+=" · "+Loc.t("Syncing…");return value;}
    void updateStatus(){if(status!=null)status.setText(syncStatus());}
    void syncIndicator(boolean show){if(syncSpinner!=null)syncSpinner.setVisibility(show||syncing?View.VISIBLE:View.GONE);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
